def find_number_of_lis(nums: list[int]) -> int:
    ranks = {v: r + 1 for r, v in enumerate(sorted(set(nums)))}
    size = len(ranks)
    best_len = [0] * (size + 1)   # Fenwick nodes: best length in the node's range
    best_ways = [0] * (size + 1)  # and how many subsequences reach it

    def query(r):
        length, ways = 0, 0
        while r > 0:
            if best_len[r] > length:
                length, ways = best_len[r], best_ways[r]
            elif best_len[r] == length:
                ways += best_ways[r]
            r -= r & -r
        return length, ways

    def update(r, length, ways):
        while r <= size:
            if length > best_len[r]:
                best_len[r], best_ways[r] = length, ways
            elif length == best_len[r]:
                best_ways[r] += ways
            r += r & -r

    for x in nums:
        length, ways = query(ranks[x] - 1)   # strictly smaller values only
        if length == 0:
            ways = 1
        update(ranks[x], length + 1, ways)
    return query(size)[1]

def find_all_concatenated_words_in_a_dict(words: list[str]) -> list[str]:
    dictionary = set(words)
    longest = max(len(w) for w in words)
    result = []
    for word in words:
        n = len(word)
        ok = [False] * (n + 1)
        ok[0] = True
        for end in range(1, n + 1):
            for start in range(max(0, end - longest), end):
                if start == 0 and end == n:
                    continue  # the word itself is not a valid single piece
                if ok[start] and word[start:end] in dictionary:
                    ok[end] = True
                    break
        if ok[n]:
            result.append(word)
    return result

