def find_answer(n: int, edges: list[list[int]]) -> list[bool]:
    graph = [[] for _ in range(n)]
    for a, b, w in edges:
        graph[a].append((b, w))
        graph[b].append((a, w))

    def dijkstra(source):
        dist = [float("inf")] * n
        dist[source] = 0
        heap = [(0, source)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))
        return dist

    from_start = dijkstra(0)
    total = from_start[n - 1]
    if total == float("inf"):
        return [False] * len(edges)
    from_end = dijkstra(n - 1)
    return [from_start[a] + w + from_end[b] == total or from_start[b] + w + from_end[a] == total
            for a, b, w in edges]

def pour_water(heights: list[int], volume: int, k: int) -> list[int]:
    levels = heights[:]
    n = len(levels)
    for _ in range(volume):
        for step in (-1, 1):            # left has priority over right
            pos = best = k
            while 0 <= pos + step < n and levels[pos + step] <= levels[pos]:
                pos += step
                if levels[pos] < levels[best]:
                    best = pos          # first column at a new lowest level
            if best != k:
                levels[best] += 1
                break
        else:
            levels[k] += 1              # nowhere lower to go
    return levels

