class MyCircularDeque:
    def __init__(self, k: int):
        self.slots = [0] * k
        self.capacity = k
        self.front = 0   # index of the first item
        self.size = 0

    def insertFront(self, value: int) -> bool:
        if self.size == self.capacity:
            return False
        self.front = (self.front - 1) % self.capacity
        self.slots[self.front] = value
        self.size += 1
        return True

    def insertLast(self, value: int) -> bool:
        if self.size == self.capacity:
            return False
        self.slots[(self.front + self.size) % self.capacity] = value
        self.size += 1
        return True

    def deleteFront(self) -> bool:
        if self.size == 0:
            return False
        self.front = (self.front + 1) % self.capacity
        self.size -= 1
        return True

    def deleteLast(self) -> bool:
        if self.size == 0:
            return False
        self.size -= 1
        return True

    def getFront(self) -> int:
        return self.slots[self.front] if self.size else -1

    def getRear(self) -> int:
        if self.size == 0:
            return -1
        return self.slots[(self.front + self.size - 1) % self.capacity]

    def isEmpty(self) -> bool:
        return self.size == 0

    def isFull(self) -> bool:
        return self.size == self.capacity

