def lowest_common_ancestor(root: TreeNode, nodes: list[TreeNode]) -> TreeNode:
    targets = set(nodes)
    report = {None: None}  # node -> lowest common ancestor of targets in its subtree
    stack = [(root, False)]
    while stack:
        node, children_done = stack.pop()
        if node is None:
            continue
        if not children_done:
            stack.append((node, True))
            stack.append((node.left, False))
            stack.append((node.right, False))
            continue
        if node in targets:
            report[node] = node
        else:
            left, right = report[node.left], report[node.right]
            report[node] = node if left and right else (left or right)
    return report[root]

