def shortest_common_supersequence(str1: str, str2: str) -> str:
    m, n = len(str1), len(str2)
    # lcs[i][j] = length of the longest common subsequence of str1[i:] and str2[j:]
    lcs = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m - 1, -1, -1):
        row, below, a = lcs[i], lcs[i + 1], str1[i]
        for j in range(n - 1, -1, -1):
            if a == str2[j]:
                row[j] = below[j + 1] + 1
            else:
                row[j] = below[j] if below[j] >= row[j + 1] else row[j + 1]

    out = []
    i = j = 0
    while i < m and j < n:
        if str1[i] == str2[j]:          # shared character, write it once
            out.append(str1[i]); i += 1; j += 1
        elif lcs[i + 1][j] >= lcs[i][j + 1]:
            out.append(str1[i]); i += 1
        else:
            out.append(str2[j]); j += 1
    out.append(str1[i:])
    out.append(str2[j:])
    return "".join(out)

def longest_palindrome(words: list[str]) -> int:
    counts = Counter(words)
    length = 0
    has_center = False
    for word, k in counts.items():
        if word[0] == word[1]:
            length += (k // 2) * 4          # pair copies on both sides
            if k % 2:
                has_center = True           # one spare copy could sit in the middle
        elif word[0] < word[1]:             # handle each mirrored pair of words once
            length += min(k, counts.get(word[::-1], 0)) * 4
    return length + (2 if has_center else 0)

