def all_possible_fbt(n: int) -> List[Optional[TreeNode]]:
    if n % 2 == 0:
        return []
    trees = {1: [TreeNode(0)]}            # size -> list of full trees with that many nodes
    for size in range(3, n + 1, 2):
        built = []
        for left_size in range(1, size - 1, 2):
            right_size = size - 1 - left_size
            for left in trees[left_size]:
                for right in trees[right_size]:
                    built.append(TreeNode(0, left, right))   # subtrees are shared
        trees[size] = built
    return trees[n]

def find_paths(m: int, n: int, max_move: int, start_row: int, start_column: int) -> int:
    MOD = 10**9 + 7
    ways = [[0] * n for _ in range(m)]   # sequences currently inside, ending at each cell
    ways[start_row][start_column] = 1
    escaped = 0
    for _ in range(max_move):
        nxt = [[0] * n for _ in range(m)]
        for r in range(m):
            row = ways[r]
            for c in range(n):
                v = row[c]
                if not v:
                    continue
                # moves that leave the grid
                escaped += v * ((r == 0) + (r == m - 1) + (c == 0) + (c == n - 1))
                # moves that stay inside
                if r > 0:
                    nxt[r - 1][c] += v
                if r < m - 1:
                    nxt[r + 1][c] += v
                if c > 0:
                    nxt[r][c - 1] += v
                if c < n - 1:
                    nxt[r][c + 1] += v
        for row in nxt:
            for c in range(n):
                row[c] %= MOD
        ways = nxt
        escaped %= MOD
    return escaped

