def min_valid_strings(words: List[str], target: str) -> int:
    m = len(target)

    def z_function(s):
        z = [0] * len(s)
        left = right = 0
        for i in range(1, len(s)):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < len(s) and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]
        return z

    # reach[i] = longest prefix of some word that matches target starting at i
    reach = [0] * m
    for word in words:
        z = z_function(word + "#" + target)
        offset = len(word) + 1
        for i in range(m):
            if z[offset + i] > reach[i]:
                reach[i] = z[offset + i]

    # minimum jumps from 0 to m where position i can jump up to reach[i]
    pieces, current_end, farthest = 0, 0, 0
    for i in range(m):
        farthest = max(farthest, i + reach[i])
        if i == current_end:
            if farthest <= i:
                return -1
            pieces += 1
            current_end = farthest
            if current_end >= m:
                return pieces
    return -1

