def find_closest_leaf(root: Optional[TreeNode], k: int) -> int:
    # Record parents and find the start node.
    parent = {root: None}
    start = None
    stack = [root]
    while stack:
        node = stack.pop()
        if node.val == k:
            start = node
        for child in (node.left, node.right):
            if child:
                parent[child] = node
                stack.append(child)
    # Breadth first search: the first leaf reached is the closest.
    queue, seen = deque([start]), {start}
    while queue:
        node = queue.popleft()
        if node.left is None and node.right is None:
            return node.val
        for nb in (node.left, node.right, parent[node]):
            if nb and nb not in seen:
                seen.add(nb)
                queue.append(nb)
    return -1

