def min_moves(target: int, max_doubles: int) -> int:
    moves = 0
    # Walk backwards from target, halving as early as possible.
    while target > 1 and max_doubles > 0:
        if target % 2 == 1:
            target -= 1      # undo an increment so we can halve
            moves += 1
        target //= 2         # undo a doubling
        max_doubles -= 1
        moves += 1
    # Remaining distance is covered by increments only.
    return moves + (target - 1)

def check_straight_line(coordinates: List[List[int]]) -> bool:
    x0, y0 = coordinates[0]
    x1, y1 = coordinates[1]
    dx, dy = x1 - x0, y1 - y0
    for x, y in coordinates[2:]:
        # Cross product of (dx, dy) and (x - x0, y - y0) must vanish.
        if dx * (y - y0) != dy * (x - x0):
            return False
    return True

def find_the_city(n: int, edges: List[List[int]], distance_threshold: int) -> int:
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def reachable_count(src: int) -> int:
        dist = {src: 0}
        heap = [(0, src)]
        settled = 0
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue  # stale entry
            settled += 1
            for v, w in graph[u]:
                nd = d + w
                if nd <= distance_threshold and nd < dist.get(v, nd + 1):
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))
        return settled - 1  # exclude the source itself

    best_city, best_count = -1, n + 1
    for city in range(n):
        cnt = reachable_count(city)
        if cnt <= best_count:  # <= lets larger labels win ties
            best_city, best_count = city, cnt
    return best_city

