def pseudo_palindromic_paths(root: Optional[TreeNode]) -> int:
    count = 0
    stack = [(root, 0)]
    while stack:
        node, mask = stack.pop()
        mask ^= 1 << node.val  # flip parity of this digit
        if node.left is None and node.right is None:
            # At most one digit with odd count means at most one set bit.
            if mask & (mask - 1) == 0:
                count += 1
            continue
        if node.left:
            stack.append((node.left, mask))
        if node.right:
            stack.append((node.right, mask))
    return count

