class SQL:
    def __init__(self, names: list[str], columns: list[int]):
        # name -> [column count, next id, {row id: row values}]
        self.tables = {name: [cols, 1, {}] for name, cols in zip(names, columns)}

    def ins(self, name: str, row: list[str]) -> bool:
        table = self.tables.get(name)
        if table is None or len(row) != table[0]:
            return False
        table[2][table[1]] = list(row)
        table[1] += 1             # ids are never reused
        return True

    def rmv(self, name: str, rowId: int) -> None:
        table = self.tables.get(name)
        if table is not None:
            table[2].pop(rowId, None)

    def sel(self, name: str, rowId: int, columnId: int) -> str:
        table = self.tables.get(name)
        if table is None or rowId not in table[2] or not 1 <= columnId <= table[0]:
            return "<null>"
        return table[2][rowId][columnId - 1]

    def exp(self, name: str) -> list[str]:
        table = self.tables.get(name)
        if table is None:
            return []
        # Insertion order equals increasing id order.
        return [",".join([str(rid)] + vals) for rid, vals in table[2].items()]

