def min_days(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    cells = [(r, c) for r in range(m) for c in range(n) if grid[r][c] == 1]
    if not cells:
        return 0
    index = {cell: i for i, cell in enumerate(cells)}
    adj = [[] for _ in cells]
    for (r, c), i in index.items():
        for nb in ((r + 1, c), (r, c + 1)):
            j = index.get(nb)
            if j is not None:
                adj[i].append(j)
                adj[j].append(i)

    total = len(cells)
    disc = [-1] * total
    low = [0] * total
    parent = [-1] * total
    next_edge = [0] * total
    disc[0] = low[0] = 0
    timer = 1
    root_children = 0
    has_cut = False
    stack = [0]
    while stack:  # iterative Tarjan
        u = stack[-1]
        if next_edge[u] < len(adj[u]):
            v = adj[u][next_edge[u]]
            next_edge[u] += 1
            if disc[v] == -1:
                parent[v] = u
                disc[v] = low[v] = timer
                timer += 1
                stack.append(v)
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])  # back edge
        else:
            stack.pop()
            p = parent[u]
            if p != -1:
                low[p] = min(low[p], low[u])
                if parent[p] == -1:
                    root_children += 1
                elif low[u] >= disc[p]:
                    has_cut = True

    if timer < total:
        return 0          # more than one island already
    if total == 1:
        return 1          # removing the only cell leaves no island
    if has_cut or root_children > 1:
        return 1
    return 2

