def leftmost_building_queries(heights: List[int], queries: List[List[int]]) -> List[int]:
    n = len(heights)
    ans = [-1] * len(queries)
    pending = [[] for _ in range(n)]  # pending[b] = list of (needed height, query id)
    for qi, (a, b) in enumerate(queries):
        if a > b:
            a, b = b, a
        if a == b or heights[a] < heights[b]:
            ans[qi] = b
        else:
            pending[b].append((heights[a], qi))

    # stack[0] is the farthest index; heights strictly decrease toward stack[-1].
    stack = []
    for i in range(n - 1, -1, -1):
        # stack now covers the suffix i + 1 .. n - 1
        for need, qi in pending[i]:
            # Find the largest position whose height exceeds need.
            lo, hi = 0, len(stack) - 1
            best = -1
            while lo <= hi:
                mid = (lo + hi) // 2
                if heights[stack[mid]] > need:
                    best = mid
                    lo = mid + 1
                else:
                    hi = mid - 1
            if best != -1:
                ans[qi] = stack[best]
        while stack and heights[stack[-1]] <= heights[i]:
            stack.pop()
        stack.append(i)
    return ans

def count_collisions(directions: str) -> int:
    left, right = 0, len(directions) - 1
    while left <= right and directions[left] == "L":
        left += 1      # escapes to the left
    while right >= left and directions[right] == "R":
        right -= 1     # escapes to the right
    # Every remaining moving car stops exactly once, scoring 1 each.
    return sum(1 for i in range(left, right + 1) if directions[i] != "S")

def min_cost(n: int, cost: List[List[int]]) -> int:
    states = [(a, b) for a in range(3) for b in range(3) if a != b]
    # Pair 0 is (house 0, house n - 1).
    dp = [cost[0][a] + cost[n - 1][b] for a, b in states]
    for i in range(1, n // 2):
        left, right = cost[i], cost[n - 1 - i]
        new_dp = []
        for c, d in states:
            best = min(dp[k] for k, (a, b) in enumerate(states) if a != c and b != d)
            new_dp.append(best + left[c] + right[d])
        dp = new_dp
    return min(dp)

