def find_tilt(root: Optional[TreeNode]) -> int:
    if root is None:
        return 0
    total = 0
    sums = {None: 0}
    stack = [(root, False)]
    while stack:
        node, children_done = stack.pop()
        if children_done:
            left, right = sums[node.left], sums[node.right]
            total += abs(left - right)          # this node's tilt
            sums[node] = left + right + node.val
        else:
            stack.append((node, True))          # revisit after children
            if node.right:
                stack.append((node.right, False))
            if node.left:
                stack.append((node.left, False))
    return total

